import { readFileSync } from 'node:fs';

// Server copy of the app's push_* strings, one map per app locale
// (generated by scripts/sync_push_strings.mjs from assets/l10n).
// UZ: Ilovaning push_* qatorlarining serverdagi nusxasi, har bir ilova tili uchun bitta xarita
// (assets/l10n dan scripts/sync_push_strings.mjs tomonidan yaratilgan).
const STRINGS = JSON.parse(readFileSync(new URL('./push_strings.json', import.meta.url), 'utf8'));
const DEFAULT_LANG = 'ja';
const WEEKDAYS_JA = '日月火水木金土';
const WEEKDAY_KANJI = '日月火水木金土';

/** App locale code the push is written in; unknown/missing → Japanese. */
// UZ: Push xabari yozilgan ilova tili kodi; noma'lum/mavjud bo'lmasa → yaponcha.
export const pushLang = (lang) => (typeof lang === 'string' && STRINGS[lang] ? lang : DEFAULT_LANG);

/** Translated push string with `{name}` placeholders filled from [params]. */
// UZ: [params] dan to'ldirilgan `{name}` o'rnini bosuvchi belgilarga ega tarjima qilingan push qatori.
export function pt(lang, key, params = {}) {
  const template = STRINGS[pushLang(lang)][key] ?? STRINGS[DEFAULT_LANG][key] ?? key;
  return template.replace(/\{(\w+)\}/g, (m, name) => (name in params ? String(params[name] ?? '') : m));
}

const intlLocale = (lang) => pushLang(lang).replace('_', '-');

/** "11/5（木）" in Japanese (unchanged from before), Intl month/day/weekday elsewhere. */
// UZ: Yapon tilida "11/5（木）" (avvalgidek o'zgarishsiz), boshqa joylarda Intl oy/kun/hafta kuni.
export function formatPushDate(iso, lang) {
  const [y, m, d] = iso.split('-').map(Number);
  const date = new Date(Date.UTC(y, m - 1, d));
  if (pushLang(lang) === 'ja') return `${m}/${d}（${WEEKDAYS_JA[date.getUTCDay()]}）`;
  return new Intl.DateTimeFormat(intlLocale(lang), {
    month: 'numeric', day: 'numeric', weekday: 'short', timeZone: 'UTC',
  }).format(date);
}

/** Localized weekday for a canonical kanji day ('月'…'日'); unknown → as is. */
// UZ: Kanonik kanji kuni ('月'…'日') uchun mahalliylashtirilgan hafta kuni; noma'lum → o'z holicha.
export function weekdayName(kanji, lang) {
  const i = WEEKDAY_KANJI.indexOf(kanji);
  if (i < 0 || !kanji) return String(kanji ?? '');
  if (pushLang(lang) === 'ja') return `${kanji}曜日`;
  // 2023-01-01 was a Sunday (index 0).
  // UZ: 2023-01-01 yakshanba bo'lgan (indeks 0).
  return new Intl.DateTimeFormat(intlLocale(lang), { weekday: 'long', timeZone: 'UTC' })
    .format(new Date(Date.UTC(2023, 0, 1 + i)));
}

/**
 * Groups recipients by language and calls [build](lang) once per language.
 * recipients: [{ token, lang }]; returns [{ lang, tokens: [..unique] }].
 * UZ: Qabul qiluvchilarni til bo'yicha guruhlaydi va har bir til uchun
 * [build](lang) chaqiradi. recipients: [{ token, lang }]; [{ lang, tokens: [..unique] }] qaytaradi.
 */
export function groupByLang(recipients) {
  const groups = new Map();
  for (const { token, lang } of recipients) {
    if (!token) continue;
    const l = pushLang(lang);
    if (!groups.has(l)) groups.set(l, new Set());
    groups.get(l).add(token);
  }
  return [...groups].map(([lang, tokens]) => ({ lang, tokens: [...tokens] }));
}

/** users/{uid} data → push recipient (token may be missing). */
// UZ: users/{uid} ma'lumotlari → push qabul qiluvchi (token mavjud bo'lmasligi mumkin).
export const recipientOf = (data) => ({ token: data?.fcmToken, lang: data?.language });
